// =====================================================================
// Report SDR - calculo UNIFICADO (Inbound / Remarketing / Advisor)
//
// MODO vem do no "Preparar" (diario = ontem | semanal = 7 dias ate ontem).
// Calcula TODOS os baldes de canal de uma vez. Quem decide o que vira
// mensagem e para qual grupo vai e o no "Monta Mensagens" (lista DESTINOS).
//
// CANAL = nome_app do evento (SDR-INBOUND / SDR-REMARKETING / SDR-ADVISOR).
// FUSO: America/Sao_Paulo.
// =====================================================================

const MODO = $('Preparar').first().json.modo;   // 'diario' | 'semanal'

const OFFSET_MIN = -180;
const DIA_MS = 86400000;

function diaLocal(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  if (isNaN(d)) return null;
  const l = new Date(d.getTime() + OFFSET_MIN * 60000);
  return Date.UTC(l.getUTCFullYear(), l.getUTCMonth(), l.getUTCDate());
}
function tsLocal(iso) { const d = new Date(iso); return isNaN(d) ? null : d.getTime(); }

const agoraLocal = new Date(Date.now() + OFFSET_MIN * 60000);
const HOJE = Date.UTC(agoraLocal.getUTCFullYear(), agoraLocal.getUTCMonth(), agoraLocal.getUTCDate());
const FIM = HOJE - DIA_MS;                                   // ontem, sempre
const INICIO = MODO === 'semanal' ? HOJE - 7 * DIA_MS : FIM; // 7 dias ou so ontem

function noPeriodo(t) { return t !== null && t >= INICIO && t <= FIM; }
function ddmm(t) {
  const d = new Date(t);
  return String(d.getUTCDate()).padStart(2, '0') + '/' + String(d.getUTCMonth() + 1).padStart(2, '0');
}

// ---------------------------------------------------------------------
// 1. Eventos
// ---------------------------------------------------------------------
const eventos = $('Eventos SDR - Ler').all().map(i => i.json);

function parsePayload(p) {
  try { return typeof p === 'string' ? JSON.parse(p) : (p || {}); } catch (e) { return {}; }
}
function templateDoEvento(e) { return e.tipo_disparo || parsePayload(e.payload).template || null; }
function canalPorApp(app) {
  const a = String(app || '').toUpperCase();
  if (a.indexOf('ADVISOR') >= 0) return 'advisor';
  if (a.indexOf('INBOUND') >= 0) return 'inbound';
  if (a.indexOf('REMARKETING') >= 0) return 'remarketing';
  if (a.indexOf('OUTBOUND') >= 0) return 'outbound';
  return null;
}
function canalPorTemplate(tpl) {
  const t = String(tpl || '').toLowerCase();
  if (t.indexOf('advisor') >= 0) return 'advisor';
  if (t.indexOf('inbound') >= 0) return 'inbound';
  if (t.indexOf('outbound') >= 0) return 'outbound';
  if (/^mensagem_\d+/.test(t)) return 'remarketing';
  return null;
}
function canalPorMidiaNome(nome) {
  const n = String(nome || '').toLowerCase();
  if (n.indexOf('advisor') >= 0) return 'advisor';
  if (n.indexOf('inbound') >= 0) return 'inbound';
  if (n.indexOf('remarketing') >= 0) return 'remarketing';
  if (n.indexOf('parceria') >= 0) return 'parcerias';
  if (n.indexOf('outbound') >= 0) return 'outbound';
  return null;
}
function tentativaDoTemplate(tpl) {
  const t = String(tpl || '');
  if (/disparo_inicial/.test(t)) return 'inicial';
  const m = t.match(/mensagem_(\d+)/);
  return m ? m[1] : null;
}
// Degrau da regua do Advisor a partir do nome do template.
function reguaAdvisor(tpl) {
  const t = String(tpl || '').toLowerCase();
  if (/ultima_tentativa|ultima/.test(t)) return '3';
  if (/followup_2d|followup|2d/.test(t)) return '2';
  if (/disparo_inicial|cadastro_frio|inicial/.test(t)) return '1';
  return null;
}
function chaveLead(e) {
  if (e.mailing_id !== null && e.mailing_id !== undefined && e.mailing_id !== '') return 'm' + e.mailing_id;
  const tel = String(e.telefone || '').replace(/\D/g, '');
  return tel ? 't' + tel.slice(-11) : null;
}

const CANAIS = ['inbound', 'remarketing', 'advisor', 'outbound', 'parcerias', 'outros'];
function novoBalde() {
  return {
    disparos: 0, falhas: 0,
    disparos_t: { inicial: 0, '1': 0, '2': 0, '3': 0 },
    regua: { '1': 0, '2': 0, '3': 0 },
    respostas: 0,
    respostas_t: { inicial: 0, '1': 0, '2': 0, '3': 0, sem_disparo: 0 },
    enc_advisor: 0, enc_parcerias: 0,
    calls_marcadas: 0, marcadas_log: 0, marcadas_reuniao: 0,
    calls_realizadas: 0, calls_noshow: 0,
    calls_hoje: 0, calls_a_frente: 0
  };
}
const R = {};
for (const c of CANAIS) R[c] = novoBalde();

// ---------------------------------------------------------------------
// 2. Historico de disparos por lead
// ---------------------------------------------------------------------
const historico = {};
for (const e of eventos) {
  if (e.tipo_evento !== 'disparo_enviado') continue;
  const k = chaveLead(e);
  const ts = tsLocal(e.created_at);
  if (!k || ts === null) continue;
  const tpl = templateDoEvento(e);
  (historico[k] = historico[k] || []).push({
    ts,
    canal: canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros',
    tentativa: tentativaDoTemplate(tpl)
  });
}
for (const k in historico) historico[k].sort((a, b) => a.ts - b.ts);

function canalDoLeadEm(k, ts) {
  const h = historico[k];
  if (!h || !h.length) return null;
  let canal = null;
  for (const d of h) { if (d.ts <= ts) canal = d.canal; else break; }
  return canal || h[0].canal;
}
const JANELA_ATRIB_MS = 7 * DIA_MS;
function disparoAnterior(k, ts) {
  const h = historico[k];
  if (!h) return null;
  let achado = null;
  for (const d of h) { if (d.ts <= ts) achado = d; else break; }
  if (!achado) return null;
  return { canal: achado.canal, tentativa: (ts - achado.ts) <= JANELA_ATRIB_MS ? achado.tentativa : null };
}

// ---------------------------------------------------------------------
// 3. Disparos, falhas, respostas, encaminhamentos
// ---------------------------------------------------------------------
const vistos = new Set();

for (const e of eventos) {
  const dia = diaLocal(e.created_at);
  if (!noPeriodo(dia)) continue;

  const k = chaveLead(e);
  const tipo = String(e.tipo_evento || '');

  if (tipo === 'disparo_enviado') {
    const tpl = templateDoEvento(e);
    const canal = canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros';
    const b = R[canal] || R.outros;
    const t = tentativaDoTemplate(tpl);
    b.disparos++;
    if (t) b.disparos_t[t] = (b.disparos_t[t] || 0) + 1;
    if (canal === 'advisor') { const g = reguaAdvisor(tpl); if (g) b.regua[g]++; }

  } else if (tipo === 'disparo_falhou') {
    const tpl = templateDoEvento(e);
    const b = R[canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros'] || R.outros;
    b.falhas++;

  } else if (tipo === 'resposta_recebida') {
    const ts = tsLocal(e.created_at);
    const ant = k ? disparoAnterior(k, ts) : null;
    const b = R[canalPorApp(e.nome_app) || (ant && ant.canal) || 'outros'] || R.outros;
    const tent = ant && ant.tentativa ? ant.tentativa : 'sem_disparo';
    const chave = (k || 'evt' + e.id) + '_' + dia;
    if (!vistos.has(chave)) {
      vistos.add(chave);
      b.respostas++;
      b.respostas_t[tent] = (b.respostas_t[tent] || 0) + 1;
    }

  } else if (/encaminh/i.test(tipo)) {
    const p = parsePayload(e.payload);
    const raw = String(p.destino || tipo).toLowerCase();
    const destino = /parceri/.test(raw) ? 'parcerias' : (/advisor/.test(raw) ? 'advisor' : null);
    if (!destino) continue;
    const b = R[canalPorApp(e.nome_app) || (k && canalDoLeadEm(k, tsLocal(e.created_at))) || 'outros'] || R.outros;
    b[destino === 'advisor' ? 'enc_advisor' : 'enc_parcerias']++;
  }
}

// ---------------------------------------------------------------------
// 4. Calls
// ---------------------------------------------------------------------
function chavesDe(mailingId, telefone) {
  const ks = [];
  if (mailingId !== null && mailingId !== undefined && mailingId !== '') ks.push('m' + mailingId);
  const t = String(telefone || '').replace(/\D/g, '');
  if (t) ks.push('t' + t.slice(-11));
  return ks;
}
const marcadasVistas = new Set();
function jaMarcada(chaves, dia) { return chaves.some(k => marcadasVistas.has(k + '_' + dia)); }
function registraMarcada(chaves, dia) { chaves.forEach(k => marcadasVistas.add(k + '_' + dia)); }

