const periodo = inp.periodo;
const CANAIS = Object.keys(R);

function taxa(num, den) {
  return den > 0 ? `taxa ${(num / den * 100).toFixed(1).replace('.', ',')}%` : 'sem disparos no período';
}

function corpoSdr(b) {
  return `📤 *DISPAROS*
${b.disparos}${b.falhas ? ` (falhas: ${b.falhas})` : ''}

💬 *RESPOSTAS* (leads distintos que responderam)
${b.respostas} — ${taxa(b.respostas, b.disparos)}

➡️ *ENCAMINHAMENTOS*
Advisor: ${b.enc_advisor} | Parcerias: ${b.enc_parcerias}

📅 *CALLS*
Agendadas: ${b.calls_marcadas}
Realizadas: ${b.calls_realizadas} | No-show: ${b.calls_noshow}
Na agenda — hoje: ${b.calls_hoje} | à frente: ${b.calls_a_frente}`;
}

function corpoAdvisor(b) {
  const reg = b.regua;
  const temReg = (reg['1'] + reg['2'] + reg['3']) > 0;
  return `📤 *DISPAROS*
${b.disparos}${b.falhas ? ` (falhas: ${b.falhas})` : ''}${temReg ? `
   1ª: ${reg['1']} | 2º toque: ${reg['2']} | última: ${reg['3']}` : ''}

💬 *RESPOSTAS* (leads distintos que responderam)
${b.respostas} — ${taxa(b.respostas, b.disparos)}

📅 *CALLS (Meet 30 min)*
Agendadas: ${b.calls_marcadas}
Realizadas: ${b.calls_realizadas} | No-show: ${b.calls_noshow}
Na agenda — hoje: ${b.calls_hoje} | à frente: ${b.calls_a_frente}`;
}

// bloco TOTAL (so entra onde total:true)
const totalDisp = CANAIS.reduce((s, c) => s + R[c].disparos, 0);
const totalResp = CANAIS.reduce((s, c) => s + R[c].respostas, 0);
