—
*TOTAL DA OPERAÇÃO (todos os canais)*
Disparos: ${totalDisp} | Respostas: ${totalResp}
Outros canais (outbound/parcerias/sem canal): ${o.disparos + p.disparos + x.disparos} disparo(s), ${x.respostas} resposta(s) sem canal
Calls agendadas — inbound: ${i.calls_marcadas} | remarketing: ${r.calls_marcadas} | advisor: ${a.calls_marcadas} | outros: ${o.calls_marcadas + p.calls_marcadas + x.calls_marcadas}`;

const out = [];
for (const d of DESTINOS) {
  const b = R[d.canal] || R.outros;
  const corpo = d.tipo === 'advisor' ? corpoAdvisor(b) : corpoSdr(b);
  let mensagem = `*${titulo} ${d.titulo}*\n_${periodo}_\n\n${corpo}`;
  if (d.total) mensagem += blocoTotal;
  out.push({ json: { nome: d.nome, grupo: d.grupo, mensagem } });
}
return out;

