  const k = chaveLead(e);
  const tipo = String(e.tipo_evento || '');

  if (tipo === 'disparo_enviado') {
    const tpl = templateDoEvento(e);
    const canal = canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros';
    const b = R[canal] || R.outros;
    const t = tentativaDoTemplate(tpl);
    b.disparos++;
    if (t) b.disparos_t[t] = (b.disparos_t[t] || 0) + 1;
    if (canal === 'advisor') { const g = reguaAdvisor(tpl); if (g) b.regua[g]++; }

  } else if (tipo === 'disparo_falhou') {
    const tpl = templateDoEvento(e);
    const b = R[canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros'] || R.outros;
    b.falhas++;

  } else if (tipo === 'resposta_recebida') {
    const ts = tsLocal(e.created_at);
    const ant = k ? disparoAnterior(k, ts) : null;
    const b = R[canalPorApp(e.nome_app) || (ant && ant.canal) || 'outros'] || R.outros;
    const tent = ant && ant.tentativa ? ant.tentativa : 'sem_disparo';
    const chave = (k || 'evt' + e.id) + '_' + dia;
    if (!vistos.has(chave)) {
      vistos.add(chave);
      b.respostas++;
      b.respostas_t[tent] = (b.respostas_t[tent] || 0) + 1;
    }

  } else if (/encaminh/i.test(tipo)) {
    const p = parsePayload(e.payload);
    const raw = String(p.destino || tipo).toLowerCase();
    const destino = /parceri/.test(raw) ? 'parcerias' : (/advisor/.test(raw) ? 'advisor' : null);
    if (!destino) continue;
    const b = R[canalPorApp(e.nome_app) || (k && canalDoLeadEm(k, tsLocal(e.created_at))) || 'outros'] || R.outros;
    b[destino === 'advisor' ? 'enc_advisor' : 'enc_parcerias']++;
  }
}

// ---------------------------------------------------------------------
// 4. Calls
// ---------------------------------------------------------------------
function chavesDe(mailingId, telefone) {
  const ks = [];
  if (mailingId !== null && mailingId !== undefined && mailingId !== '') ks.push('m' + mailingId);
  const t = String(telefone || '').replace(/\D/g, '');
  if (t) ks.push('t' + t.slice(-11));
  return ks;
}
const marcadasVistas = new Set();
function jaMarcada(chaves, dia) { return chaves.some(k => marcadasVistas.has(k + '_' + dia)); }
function registraMarcada(chaves, dia) { chaves.forEach(k => marcadasVistas.add(k + '_' + dia)); }

const reunioesLista = $('Reunioes SDR - Ler').all().map(i => i.json);
const reunioesPorLead = {};
for (const r of reunioesLista) {
  const canal = canalPorApp(r.origem);
  if (!canal) continue;
  const chaves = [];
  if (r.mailing_id) chaves.push('m' + r.mailing_id);
  const tel = String(r.telefone || '').replace(/\D/g, '');
  if (tel) chaves.push('t' + tel.slice(-11));
  const marcos = [tsLocal(r.criado_em), tsLocal(r.data_hora_agendada)].filter(t => t !== null);
  for (const c of chaves) (reunioesPorLead[c] = reunioesPorLead[c] || []).push({ canal, marcos });
}
function canalPorReuniao(chaves, ts) {
  let melhor = null, menor = Infinity;
  for (const c of chaves) {
    for (const r of (reunioesPorLead[c] || [])) {
      for (const m of r.marcos) {
        const d = Math.abs(m - ts);
        if (d < menor) { menor = d; melhor = r.canal; }
      }
    }
  }
  return melhor;
}
function canalDaCall(row, ts) {
  const chaves = [];
  if (row.mailing_id !== null && row.mailing_id !== undefined && row.mailing_id !== '') chaves.push('m' + row.mailing_id);
  const tel = String(row.telefone || '').replace(/\D/g, '');
  if (tel) chaves.push('t' + tel.slice(-11));
  return canalPorReuniao(chaves, ts)
      || (chaves.length ? canalDoLeadEm(chaves[0], ts) : null)
      || canalPorMidiaNome(row.midia_nome)
      || 'outros';
}

for (const row of $('agenda').all().map(i => i.json).filter(r => r && r.evento)) {
  const dia = row.dia ? diaLocal(String(row.dia).slice(0, 10) + 'T12:00:00Z') : null;
  const b = R[canalDaCall(row, dia !== null ? dia : Date.now())] || R.outros;
  if (row.evento === 'agendada_hoje') { b.calls_hoje++; continue; }
  if (row.evento === 'agendada_frente') { b.calls_a_frente++; continue; }
  if (!noPeriodo(dia)) continue;
  if (row.evento === 'marcada') {
    const ch = chavesDe(row.mailing_id, row.telefone);
    if (!jaMarcada(ch, dia)) { registraMarcada(ch, dia); b.calls_marcadas++; b.marcadas_log++; }
  }
  else if (row.evento === 'realizada') b.calls_realizadas++;
  else if (row.evento === 'no_show') b.calls_noshow++;
}

for (const r of reunioesLista) {
  const dia = diaLocal(r.criado_em);
  if (!noPeriodo(dia)) continue;
  const ch = chavesDe(r.mailing_id, r.telefone);
  if (!ch.length || jaMarcada(ch, dia)) continue;
  registraMarcada(ch, dia);
  const canal = canalPorApp(r.origem) || canalDoLeadEm(ch[0], tsLocal(r.criado_em)) || 'outros';
  const b = R[canal] || R.outros;
  b.calls_marcadas++;
  b.marcadas_reuniao++;
}

// ---------------------------------------------------------------------
// 5. Saida: R completo + metadados do periodo. Mensagens saem no proximo no.
// ---------------------------------------------------------------------
const titulo = MODO === 'semanal' ? 'RESUMO SEMANAL' : 'REPORT';
const periodo = MODO === 'semanal'
  ? `Semana ${ddmm(INICIO)} → ${ddmm(FIM)}`
  : `Ontem ${ddmm(FIM)}`;

return [{ json: { modo: MODO, titulo, periodo, inicio: ddmm(INICIO), fim: ddmm(FIM), R } }];

// =====================================================================
// MONTA MENSAGENS  ->  1 item por report, cada um com {grupo, mensagem}
//
// PARA ADICIONAR / TROCAR UM REPORT, mexa SO na lista DESTINOS abaixo.
//   grupo  = JID do grupo do WhatsApp (o "numero" do grupo)
//   canal  = qual balde do calculo entra na mensagem
//            ('inbound' | 'remarketing' | 'advisor' | 'outbound' | 'parcerias')
//   titulo = sufixo do cabecalho (*REPORT <titulo>*)
//   tipo   = 'sdr' (disparos/respostas/encaminhamentos/calls)
//            'advisor' (disparos c/ regua + respostas + calls Meet)
//   total  = true -> anexa o bloco "TOTAL DA OPERACAO" no fim
// =====================================================================

const GRUPO_SDR     = '120363425631150537@g.us';
const GRUPO_ADVISOR = '120363429028125575@g.us';

const DESTINOS = [
  { nome: 'inbound',     grupo: GRUPO_SDR,     canal: 'inbound',     titulo: 'INBOUND',     tipo: 'sdr',     total: false },
  { nome: 'remarketing', grupo: GRUPO_SDR,     canal: 'remarketing', titulo: 'REMARKETING', tipo: 'sdr',     total: true  },
  { nome: 'advisor',     grupo: GRUPO_ADVISOR, canal: 'advisor',     titulo: 'ADVISOR',     tipo: 'advisor', total: false },
];

// ---------------------------------------------------------------------
const inp = $json;              // { modo, titulo, periodo, R }
const R = inp.R;
const titulo = inp.titulo;      // REPORT | RESUMO SEMANAL
const periodo = inp.periodo;
const CANAIS = Object.keys(R);

function taxa(num, den) {
  return den > 0 ? `taxa ${(num / den * 100).toFixed(1).replace('.', ',')}%` : 'sem disparos no período';
}

function corpoSdr(b) {
  return `📤 *DISPAROS*
${b.disparos}${b.falhas ? ` (falhas: ${b.falhas})` : ''}

💬 *RESPOSTAS* (leads distintos que responderam)
${b.respostas} — ${taxa(b.respostas, b.disparos)}

➡️ *ENCAMINHAMENTOS*
Advisor: ${b.enc_advisor} | Parcerias: ${b.enc_parcerias}

📅 *CALLS*
Agendadas: ${b.calls_marcadas}
Realizadas: ${b.calls_realizadas} | No-show: ${b.calls_noshow}
Na agenda — hoje: ${b.calls_hoje} | à frente: ${b.calls_a_frente}`;
}

function corpoAdvisor(b) {
  const reg = b.regua;
  const temReg = (reg['1'] + reg['2'] + reg['3']) > 0;
  return `📤 *DISPAROS*
${b.disparos}${b.falhas ? ` (falhas: ${b.falhas})` : ''}${temReg ? `
   1ª: ${reg['1']} | 2º toque: ${reg['2']} | última: ${reg['3']}` : ''}

💬 *RESPOSTAS* (leads distintos que responderam)
${b.respostas} — ${taxa(b.respostas, b.disparos)}

📅 *CALLS (Meet 30 min)*
Agendadas: ${b.calls_marcadas}
Realizadas: ${b.calls_realizadas} | No-show: ${b.calls_noshow}
Na agenda — hoje: ${b.calls_hoje} | à frente: ${b.calls_a_frente}`;
}

// bloco TOTAL (so entra onde total:true)
const totalDisp = CANAIS.reduce((s, c) => s + R[c].disparos, 0);
const totalResp = CANAIS.reduce((s, c) => s + R[c].respostas, 0);
const o = R.outbound, p = R.parcerias, x = R.outros, i = R.inbound, r = R.remarketing, a = R.advisor;
const blocoTotal = `

—
*TOTAL DA OPERAÇÃO (todos os canais)*
Disparos: ${totalDisp} | Respostas: ${totalResp}
Outros canais (outbound/parcerias/sem canal): ${o.disparos + p.disparos + x.disparos} disparo(s), ${x.respostas} resposta(s) sem canal
Calls agendadas — inbound: ${i.calls_marcadas} | remarketing: ${r.calls_marcadas} | advisor: ${a.calls_marcadas} | outros: ${o.calls_marcadas + p.calls_marcadas + x.calls_marcadas}`;

const out = [];
for (const d of DESTINOS) {
  const b = R[d.canal] || R.outros;
  const corpo = d.tipo === 'advisor' ? corpoAdvisor(b) : corpoSdr(b);
  let mensagem = `*${titulo} ${d.titulo}*\n_${periodo}_\n\n${corpo}`;
  if (d.total) mensagem += blocoTotal;
  out.push({ json: { nome: d.nome, grupo: d.grupo, mensagem } });
}
return out;
